-- Generated by .tools/build_brand_asset.py from the supplied brand image.
return function()
    local loader=getcustomasset or getsynasset
    if type(loader)~="function" or type(writefile)~="function" then return nil end
    local path="Overlay/Assets/plex-logo-2340651a9df2.png"
    local ok,result=pcall(function()
        if not isfile or not isfile(path) then
            if makefolder and isfolder then
                if not isfolder("Overlay") then makefolder("Overlay") end
                if not isfolder("Overlay/Assets") then makefolder("Overlay/Assets") end
            end
            local hex=""
            writefile(path,(hex:gsub("..",function(byte)return string.char(tonumber(byte,16))end)))
        end
        return loader(path)
    end)
    return ok and result or nil
end
